"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { PlusIcon } from "../parts/icons";
import { AddEndpointForm } from "./webhooks/add-endpoint-form";
import { CopyIconButton } from "./copy-icon-button";
import { ENDPOINTS, type Endpoint, failingCount } from "./webhooks/data";
import { DeliveryList } from "./webhooks/delivery-list";
import { EndpointList } from "./webhooks/endpoint-list";
import { EventBars } from "./webhooks/event-bars";
import { PayloadInspector } from "./webhooks/payload-inspector";

const RETRY_MS = 1100;

/** Marks a retried delivery as delivered and moves its post from the failed count to the delivered count. */
function resolveDelivery(endpoint: Endpoint, deliveryId: string): Endpoint {
  const target = endpoint.deliveries.find((item) => item.id === deliveryId);
  if (!target) return endpoint;
  return {
    ...endpoint,
    deliveries: endpoint.deliveries.map((item) =>
      item.id === deliveryId ? { ...item, status: 200, attempts: Math.min(3, item.attempts + 1), durationMs: 148 } : item,
    ),
    hours: endpoint.hours.map((hour, index) =>
      index === target.hour && hour.failed > 0 ? { ok: hour.ok + 1, failed: hour.failed - 1 } : hour,
    ),
  };
}

/**
 * A webhooks console for Fernhill: the endpoints with their delivery rate and
 * health, an inline form to add one, and for the chosen endpoint its details,
 * posts per hour, the delivery history and an inspector that can retry a
 * failed delivery.
 */
export function Webhooks({ className }: { className?: string }) {
  const [endpoints, setEndpoints] = useState(ENDPOINTS);
  const [selectedId, setSelectedId] = useState(ENDPOINTS[0]!.id);
  const [deliveryId, setDeliveryId] = useState(ENDPOINTS[0]!.deliveries[1]!.id);
  const [freshId, setFreshId] = useState<string | null>(null);
  const [formOpen, setFormOpen] = useState(false);
  const [retryingId, setRetryingId] = useState<string | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const addButton = useRef<HTMLButtonElement>(null);
  const reduceMotion = useReducedMotion();
  const titleId = useId();

  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current);
  }, []);

  const endpoint = endpoints.find((item) => item.id === selectedId) ?? endpoints[0]!;
  const delivery = endpoint.deliveries.find((item) => item.id === deliveryId) ?? endpoint.deliveries[0];
  const failingEndpoints = endpoints.filter((item) => failingCount(item) > 0).length;

  const selectEndpoint = (id: string) => {
    setSelectedId(id);
    setDeliveryId(endpoints.find((item) => item.id === id)?.deliveries[0]?.id ?? "");
  };

  const closeForm = () => {
    setFormOpen(false);
    requestAnimationFrame(() => addButton.current?.focus());
  };

  const addEndpoint = (name: string, url: string) => {
    const id = `added-${endpoints.length + 1}`;
    const added: Endpoint = {
      id,
      name,
      url,
      addedBy: "You",
      addedOn: "Today",
      secret: `whsec_test_••••${(4096 + endpoints.length * 977).toString(16).slice(-4)}`,
      apiVersion: "2026-09-01",
      hours: Array.from({ length: 24 }, () => ({ ok: 0, failed: 0 })),
      deliveries: [],
    };
    setEndpoints([...endpoints, added]);
    setFreshId(id);
    setSelectedId(id);
    setDeliveryId("");
    setAnnouncement(`${name} added. It receives events from now on.`);
    closeForm();
  };

  const retry = () => {
    if (!delivery || retryingId) return;
    const target = { endpointId: endpoint.id, deliveryId: delivery.id };
    setRetryingId(delivery.id);
    setAnnouncement(`Retrying ${delivery.event}.`);
    timer.current = setTimeout(() => {
      setEndpoints((current) => current.map((item) => (item.id === target.endpointId ? resolveDelivery(item, target.deliveryId) : item)));
      setRetryingId(null);
      setAnnouncement("Delivered on retry. The endpoint answered 200.");
    }, RETRY_MS);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0 max-w-xl">
          <h2 id={titleId} className="text-base font-semibold">
            Webhooks
          </h2>
          <p className="text-sm text-muted-foreground">
            Fernhill signs every post with the endpoint secret. A failed post is retried 3 times over the next hour, or you can retry it now.
          </p>
          <p className="mt-2 text-xs text-muted-foreground tabular-nums">
            {endpoints.length} endpoints, {failingEndpoints === 0 ? "none failing" : `${failingEndpoints} with failed deliveries`}
          </p>
        </div>
        <Button ref={addButton} variant="outline" size="sm" aria-expanded={formOpen} onClick={() => (formOpen ? closeForm() : setFormOpen(true))}>
          <PlusIcon aria-hidden="true" className="size-4" />
          Add endpoint
        </Button>
      </header>

      <AnimatePresence initial={false}>
        {formOpen ? (
          <motion.div
            key="form"
            initial={reduceMotion ? false : { height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { height: 0, opacity: 0, transition: { duration: 0.15 } }}
            transition={{ duration: 0.22, ease: [0.2, 0, 0, 1] }}
            className="overflow-hidden"
          >
            <AddEndpointForm onAdd={addEndpoint} onClose={closeForm} />
          </motion.div>
        ) : null}
      </AnimatePresence>

      <EndpointList endpoints={endpoints} selectedId={endpoint.id} onSelect={selectEndpoint} freshId={freshId} />

      <section aria-label={`${endpoint.name} details`} className="flex flex-col gap-5 border-t border-border px-5 py-4">
        <div className="flex flex-col gap-1">
          <h3 className="text-sm font-semibold">{endpoint.name}</h3>
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
            <span>
              Added by {endpoint.addedBy} on {endpoint.addedOn}
            </span>
            <span className="flex items-center gap-1">
              Secret <code className="font-mono text-foreground">{endpoint.secret}</code>
              <CopyIconButton value={endpoint.secret} label="Copy signing secret" className="size-7" />
            </span>
            <span>API version {endpoint.apiVersion}</span>
          </div>
        </div>

        <EventBars name={endpoint.name} hours={endpoint.hours} />

        {delivery ? (
          <div className="grid gap-5 @3xl:grid-cols-[minmax(0,2fr)_minmax(0,3fr)]">
            <div className="flex min-w-0 flex-col gap-2">
              <h3 className="text-sm font-medium">Delivery history</h3>
              <DeliveryList deliveries={endpoint.deliveries} selectedId={delivery.id} onSelect={setDeliveryId} retryingId={retryingId} />
            </div>
            <PayloadInspector endpoint={endpoint} delivery={delivery} retrying={retryingId === delivery.id} onRetry={retry} />
          </div>
        ) : (
          <p className="rounded-lg border border-dashed border-border px-4 py-6 text-center text-sm text-muted-foreground">
            No deliveries yet. The next booking at any clinic posts here.
          </p>
        )}
      </section>
      <p role="status" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

