"use client";

import { type FormEvent, type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

/** Props for the inline form that adds an endpoint. */
export interface AddEndpointFormProps {
  onAdd: (name: string, url: string) => void;
  /** Closes the form. The caller returns focus to the button that opened it. */
  onClose: () => void;
}

const URL_PATTERN = /^https:\/\/[a-z0-9.-]+\.[a-z]{2,}(\/\S*)?$/i;

/**
 * Two fields, a name and an HTTPS address, that open in place under the
 * header. Escape closes the form; an address that is not HTTPS says why.
 */
export function AddEndpointForm({ onAdd, onClose }: AddEndpointFormProps) {
  const [name, setName] = useState("");
  const [url, setUrl] = useState("https://");
  const [error, setError] = useState<string | null>(null);
  const first = useRef<HTMLInputElement>(null);
  const nameId = useId();
  const urlId = useId();
  const errorId = useId();

  useEffect(() => first.current?.focus(), []);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!URL_PATTERN.test(url.trim())) {
      setError("Use a full HTTPS address, such as https://desk.your-clinic.example/hooks.");
      return;
    }
    onAdd(name.trim() || "New endpoint", url.trim());
  };

  const onKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      onClose();
    }
  };

  return (
    <form onSubmit={submit} onKeyDown={onKeyDown} aria-label="Add endpoint" className="grid gap-3 border-b border-border px-5 py-4 @xl:grid-cols-[12rem_minmax(0,1fr)_auto] @xl:items-end">
      <div className="flex flex-col gap-1.5">
        <label htmlFor={nameId} className="text-xs font-medium">
          Name
        </label>
        <Input ref={first} id={nameId} value={name} onChange={(event) => setName(event.target.value)} placeholder="Room display" />
      </div>
      <div className="flex flex-col gap-1.5">
        <label htmlFor={urlId} className="text-xs font-medium">
          Endpoint address
        </label>
        <Input
          id={urlId}
          value={url}
          inputMode="url"
          aria-invalid={error !== null}
          aria-describedby={error ? errorId : undefined}
          onChange={(event) => {
            setUrl(event.target.value);
            setError(null);
          }}
        />
      </div>
      <div className="flex gap-2">
        <Button type="button" variant="ghost" onClick={onClose}>
          Cancel
        </Button>
        <Button type="submit">Add</Button>
      </div>
      {error ? (
        <p id={errorId} role="alert" className="text-xs text-destructive @xl:col-span-3">
          {error}
        </p>
      ) : null}
    </form>
  );
}

