import { Button } from "@/components/ui/button";
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard";

import { CheckIcon } from "../parts/icons";
import { CopyIcon } from "./icons";

/** Props for a small button that copies one value. */
export interface CopyIconButtonProps {
  /** The text that lands on the clipboard. */
  value: string;
  /** Names what is copied, such as "Copy secret". */
  label: string;
  className?: string;
}

/**
 * An icon button that copies a value and shows a check for a moment. A live
 * region says "Copied" so the change is not only visual.
 */
export function CopyIconButton({ value, label, className }: CopyIconButtonProps) {
  const { state, copy } = useCopyToClipboard();
  return (
    <>
      <Button type="button" variant="ghost" size="icon" aria-label={label} className={className} onClick={() => copy(value)}>
        {state === "done" ? <CheckIcon aria-hidden="true" className="size-4" /> : <CopyIcon aria-hidden="true" className="size-4" />}
      </Button>
      <span role="status" className="sr-only">
        {state === "done" ? "Copied" : state === "error" ? "Copy failed" : ""}
      </span>
    </>
  );
}

"use client"

import { useState, useTransition } from "react"

export type CopyState = "idle" | "done" | "error"

export type UseCopyToClipboardOptions = {
  onCopySuccess?: (text: string) => void
  onCopyError?: (error: Error) => void
  resetDelay?: number
}

export function useCopyToClipboard({
  onCopySuccess,
  onCopyError,
  resetDelay = 1500,
}: UseCopyToClipboardOptions = {}) {
  const [state, setState] = useState<CopyState>("idle")
  const [, startTransition] = useTransition()

  /** Narrows the copy argument to the lazy form that produces the text. */
  const isTextFactory = (text: string | (() => string)): text is () => string =>
    typeof text === "function"

  const copy = (text: string | (() => string)) => {
    startTransition(async () => {
      try {
        const finalText = isTextFactory(text) ? text() : text
        await navigator.clipboard.writeText(finalText)
        setState("done")
        onCopySuccess?.(finalText)
      } catch (error) {
        setState("error")
        onCopyError?.(error instanceof Error ? error : new Error("Copy failed"))
      } finally {
        await new Promise((resolve) => setTimeout(resolve, resetDelay))
        setState("idle")
      }
    })
  }

  return { state, copy } as const
}

