import { seededRandom } from "../../lib/plot";

/** The events Fernhill can post to an endpoint. */
export const WEBHOOK_EVENTS = ["booking.created", "booking.cancelled", "visit.checked_in", "patient.updated"] as const;

/** One event name Fernhill posts. */
export type WebhookEvent = (typeof WEBHOOK_EVENTS)[number];

/** One hour of posts to an endpoint. */
export interface HourBucket {
  ok: number;
  failed: number;
}

/** One post to an endpoint, kept in the delivery history. */
export interface Delivery {
  id: string;
  event: WebhookEvent;
  /** The HTTP status the endpoint answered with. 0 means it timed out. */
  status: number;
  /** Clock time of the post, such as "14:32". */
  time: string;
  durationMs: number;
  /** The hour bucket the post counts in, so a retry can move it from failed to ok. */
  hour: number;
  /** How many times Fernhill has tried this post. */
  attempts: number;
}

/** One endpoint that receives Fernhill events. */
export interface Endpoint {
  id: string;
  name: string;
  url: string;
  addedBy: string;
  addedOn: string;
  /** Always a masked sample, never a real secret. */
  secret: string;
  apiVersion: string;
  hours: HourBucket[];
  deliveries: Delivery[];
}

/** How many hourly bars the chart shows. */
export const HOURS = 24;

/** The clock label of an hour bucket today, from 00:00 to 23:00. */
export const hourLabel = (hour: number) => `${String(hour).padStart(2, "0")}:00`;

function makeHours(seed: number, base: number, failures: number[]): HourBucket[] {
  const random = seededRandom(seed);
  return Array.from({ length: HOURS }, (_, hour) => {
    // Clinics book in the working day, so posts rise from 7:00 and fall after 19:00.
    const day = hour >= 7 && hour <= 19 ? 1 : 0.25;
    const ok = Math.round(base * day * (0.7 + random() * 0.6));
    return { ok, failed: failures.includes(hour) ? 1 + Math.floor(random() * 2) : 0 };
  });
}

function delivery(id: string, event: WebhookEvent, status: number, hour: number, minute: number, durationMs: number): Delivery {
  return { id, event, status, time: `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`, durationMs, hour, attempts: status >= 200 && status < 300 ? 1 : 3 };
}

/** The sample endpoints of the Fernhill webhooks console. */
export const ENDPOINTS: Endpoint[] = [
  {
    id: "front-desk",
    name: "Front desk board",
    url: "https://desk.harbour-clinic.example/hooks/fernhill",
    addedBy: "Priya Nair",
    addedOn: "4 March 2026",
    secret: "whsec_test_••••3f9a",
    apiVersion: "2026-09-01",
