import { type KeyboardEvent, useRef } from "react";

/**
 * Keyboard selection for a listbox whose options each hold the tab stop in
 * turn. Up and Down step, Home and End jump, and focus follows the selection.
 */
export function useRovingSelect(count: number, selected: number, onSelect: (index: number) => void) {
  const options = useRef<(HTMLElement | null)[]>([]);

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    const last = count - 1;
    let next: number;
    if (event.key === "ArrowDown") next = Math.min(last, selected + 1);
    else if (event.key === "ArrowUp") next = Math.max(0, selected - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = last;
    else return;
    event.preventDefault();
    onSelect(next);
    options.current[next]?.focus();
  };

  const optionRef = (index: number) => (element: HTMLElement | null) => {
    options.current[index] = element;
  };

  return { onKeyDown, optionRef };
}

